Lemma pbi_call (a ra pv h v18 : Z) (fxq : FPState) Rq Mq mdq crq kq :
  inv Mq mdq crq kq a -> PESK.sp_hb P h -> xhi + a <= h -> L5.ra_ok ra -> sp - 40 <= pv -> pv + 1 <= sp - 32 ->
  getr Rq (PMK.reg 1) = Z_to_bv 64 ra -> getr Rq (PMK.reg 2) = Z_to_bv 64 (sp - 48) ->
  getr Rq (PMK.reg 8) = Z_to_bv 64 (fb + 432) -> getr Rq (PMK.reg 9) = Z_to_bv 64 u -> getr Rq (PMK.reg 18) = Z_to_bv 64 v18 ->
  getr Rq (PMK.reg 10) = Z_to_bv 64 (sp - 48) -> getr Rq (PMK.reg 11) = Z_to_bv 64 pv -> L5.u64_at RSEGS Mq (sp - 48) (fb + 440) -> csl Rq ->
  (forall (fx2 : FPState) R2 M2 md2 cr2 k2, inv M2 md2 cr2 k2 (a + 1) ->
      getr R2 (PMK.reg 2) = Z_to_bv 64 (sp - 48) -> getr R2 (PMK.reg 8) = Z_to_bv 64 (fb + 432) -> getr R2 (PMK.reg 9) = Z_to_bv 64 u -> getr R2 (PMK.reg 18) = Z_to_bv 64 v18 -> csl R2 ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 ra M2 md2) K) ->
  srealizes RSEGS SCFG (PMSP.cfg RSEGS Rq 0x3898c Mq mdq) K.
Proof.
